/** Shared types for the Agent Arena evidence-mining agent. */

/** Competition market as served by https://competition.delphi.fyi/markets.json */
export interface CompetitionMarket {
  address: string;
  question: string;
  delphiUrl: string;
  category: string;
  marketTier: string;
  wave: number;
  status: string;
  odds: { yes: number; no: number };
  closesAt: string;
  evidenceCutoffAt: string;
  pots: { judgement: string; settlement: string };
  resolutionCriteria: string;
}

/** Mirrors the SDK EntryState (kept local so mock mode needs no API). */
export interface EntryState {
  canSubmit: boolean;
  reason?: string;
  remainingOnMarket: number;
  /** USDC.e base units (6 decimals) left in the judgment pot. Information only. */
  judgementPotRemainingBaseUnits: string;
  restricted?: boolean;
  rateLimit: { resetAt: string };
}

/** Mirrors the SDK EvidenceLimits. */
export interface EvidenceLimits {
  submitsLeftThisHour: number;
  hourEndsAt: string;
  dailyCapLeft: number;
  dailyCapResetAt: string;
}

export interface EvidenceTerms {
  version: string;
  url: string;
  acceptedAt: string | null;
}

export interface SubmissionRecord {
  id: string;
  createdAt: string;
  agentId: string | null;
  note: string | null;
  links: string[];
  status: string;
  markets: { marketAddress: string; bounty: { amount: string; state: string } | null }[];
}

/** Read-only client surface used by the pipeline. Same shape in mock and live mode. */
export interface DelphiApi {
  readonly mode: "mock" | "live";
  getLimits(): Promise<EvidenceLimits>;
  getTerms(): Promise<EvidenceTerms>;
  getEntryState(marketAddress: string): Promise<EntryState>;
  listSubmissions(query: { market?: string }): Promise<SubmissionRecord[]>;
  listCompetitionMarkets(): Promise<CompetitionMarket[]>;
}

/** Mining path per the build brief: 1 arithmetic, 2 machine-readable trackers, 3 non-English scraping. */
export type MiningPath = 1 | 2 | 3;

export type AnalysisKind =
  | "cpi_base_effect"
  | "turnout_projection"
  | "poll_margin_regression"
  | "dhondt_seats"
  | "ballot_flag_snapshot"
  | "markov_lead"
  | "threshold_velocity"
  | "release_gap_cdf"
  | "blocker_clearance";

export type AnalysisSpec = { kind: AnalysisKind; params: Record<string, unknown> };

export type LinkAccess = "static-html" | "api-json" | "scraped";

export interface SourceLink {
  url: string;
  label: string;
  lang: string;
  access: LinkAccess;
}

/** Per-market research input. The mock runs read these as fixture data; live runs
 *  re-derive `analysis.params` and `figures` from the same sources before use. */
export interface ResearchSpec {
  marketAddress: string;
  topic: string;
  miningPath: MiningPath;
  langs: string[];
  /** Dated fact headline, figures inline. Must be novel (not a priced-in headline). */
  headline: string;
  /** Key figures pasted into the note so the judge never needs JS/rendered pages. */
  figures: string[];
  /** One line per link: what the page shows at fetch time. */
  sourceDescriptions: string[];
  links: SourceLink[];
  analysis: AnalysisSpec;
}

/** Result of the Python math/CSV generator for one spec. */
export interface AnalysisResult {
  kind: AnalysisKind;
  evidenceImpliedYes: number;
  confidence: "low" | "medium" | "high";
  methodLines: string[];
  figureSummary: string;
}

/** A fully assembled submission candidate, pre-gate. */
export interface EvidenceCandidate {
  marketAddress: string;
  marketQuestion: string;
  marketImpliedYes: number;
  topic: string;
  miningPath: MiningPath;
  langs: string[];
  headline: string;
  figures: string[];
  sourceDescriptions: string[];
  links: SourceLink[];
  analysis: AnalysisResult;
  stance: "yes" | "no";
  factSignature: string;
  asOf: string;
}

export interface GateVerdict {
  pass: boolean;
  reasons: string[];
  warnings: string[];
}

export interface EvidenceLogEntry {
  ts: string;
  marketAddress: string;
  topic: string;
  stance: "yes" | "no";
  factSignature: string;
  status: "drafted" | "rejected" | "submitted";
  draftPath: string | null;
  submissionId: string | null;
  note: string;
}

export interface DraftManifest {
  topic: string;
  marketAddress: string;
  marketQuestion: string;
  generatedAt: string;
  mode: "mock" | "live";
  asOf: string;
  stance: "yes" | "no";
  links: string[];
  files: string[];
  factSignature: string;
  /** Reserved for a live submit; reused verbatim on retry. */
  idempotencyKey: string;
  submittedAt: string | null;
  submissionId: string | null;
}

export interface RunReport {
  runTs: string;
  mode: "mock" | "live";
  marketsSeen: number;
  marketsEligible: number;
  marketsConsidered: CompetitionMarket[];
  marketSkips: { address: string; question: string; reason: string }[];
  candidatesMined: number;
  draftsWritten: string[];
  duplicatesSkipped: string[];
  gateRejects: { topic: string; reasons: string[] }[];
  draftsSkippedNoSpec: { address: string; question: string; cutoff: string }[];
  feedbackDrafts: string[];
}

import { randomUUID } from "node:crypto";
import type { CompetitionMarket, EntryState, EvidenceLimits, EvidenceTerms, SubmissionRecord } from "./types.js";

/**
 * Mock Delphi state. Markets snapshot is the real Wave 1 list fetched read-only from
 * https://competition.delphi.fyi/markets.json (public, no key needed) so mock runs
 * exercise the same data as live runs. Entry states, limits, terms and submissions
 * are fixtures with a few deliberate edge cases for QA.
 */

export function loadFixtureMarkets(): CompetitionMarket[] {
  // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
  const data = require("../fixtures-markets.json") as CompetitionMarket[];
  return data;
}

const DEFAULT_ENTRY_STATE: EntryState = {
  canSubmit: true,
  remainingOnMarket: 3,
  judgementPotRemainingBaseUnits: "20000000", // $20.00 of judgment pot left
  restricted: false,
  rateLimit: { resetAt: "2026-11-26T18:00:00.000Z" },
};

/** Edge cases so the pipeline demonstrably skips unusable markets. */
const ENTRY_STATE_OVERRIDES: Record<string, Partial<EntryState>> = {
  // Per-market limit exhausted (3/3 already used by another run of this account).
  "0xbb2666746de6": { canSubmit: false, remainingOnMarket: 0, reason: "market_submission_cap" },
  // Restricted tier example: only 1 submission per market instead of 3.
  "0x48c2f4d761be": { canSubmit: true, remainingOnMarket: 1, restricted: true },
  // Judgment pot drained: submissions still allowed but pay $0 judgment bounty.
  "0xa96dc7160663": {
    canSubmit: true,
    remainingOnMarket: 3,
    judgementPotRemainingBaseUnits: "0",
  },
};

const MOCK_LIMITS: EvidenceLimits = {
  submitsLeftThisHour: 30,
  hourEndsAt: "2026-11-26T18:00:00.000Z",
  dailyCapLeft: 80,
  dailyCapResetAt: "2026-11-27T00:00:00.000Z",
};

const MOCK_TERMS: EvidenceTerms = {
  version: "2026-11-main",
  url: "https://delphi.fyi/terms",
  acceptedAt: "2026-11-25T17:30:00.000Z",
};

/** Previously submitted items on this account in mock state (dedupe realism). */
const MOCK_SUBMISSIONS: SubmissionRecord[] = [];

export function mockEntryState(address: string): EntryState {
  return { ...DEFAULT_ENTRY_STATE, ...ENTRY_STATE_OVERRIDES[address] };
}

export function mockLimits(): EvidenceLimits {
  return { ...MOCK_LIMITS };
}

export function mockTerms(): EvidenceTerms {
  return { ...MOCK_TERMS };
}

export function mockSubmissions(market?: string): SubmissionRecord[] {
  return market
    ? MOCK_SUBMISSIONS.filter((s) => s.markets.some((m) => m.marketAddress === market))
    : [...MOCK_SUBMISSIONS];
}

export const MOCK_NOW = "2026-11-26T12:00:00.000Z";
export const MOCK_RUN_ID = randomUUID();

