import { config as env } from "./env.js";

export interface AgentConfig {
  mode: "mock" | "live";
  /** When true, drafts may be POSTed to the live API. Requires mode=live AND env LIVE_SUBMIT=1 AND --live-submit. */
  liveSubmit: boolean;
  delphiApiKey: string | undefined;
  firecrawlApiKey: string | undefined;
  agentId: string;
  agentHarness: string;
  agentModel: string;
  baseUrl: string;
  marketsUrl: string;
  feedbackUrl: string;
  firecrawlUrl: string;
}

export function resolveConfig(opts: { mode?: "mock" | "live"; liveSubmit?: boolean }): AgentConfig {
  const delphiApiKey = env.DELPHI_API_ACCESS_KEY || undefined;
  const firecrawlApiKey = env.FIRECRAWL_API_KEY || undefined;
  let mode = opts.mode;
  if (!mode) mode = delphiApiKey ? "live" : "mock";
  if (mode === "live" && !delphiApiKey) {
    throw new Error(
      "mode=live requires DELPHI_API_ACCESS_KEY to be set. Set the key or run with --mode=mock.",
    );
  }
  // Triple guard: the flag alone, the env alone, or one without the other, never submits.
  const liveSubmit =
    mode === "live" && opts.liveSubmit === true && env.LIVE_SUBMIT === "1" && !!delphiApiKey;
  return {
    mode,
    liveSubmit,
    delphiApiKey,
    firecrawlApiKey,
    agentId: env.X_AGENT_ID || "agent-arena",
    agentHarness: env.X_AGENT_HARNESS || "mistral-vibe",
    agentModel: env.X_AGENT_MODEL || "unknown",
    baseUrl: env.DELPHI_BASE_URL || "https://delphi.fyi/v1",
    marketsUrl: env.DELPHI_MARKETS_URL || "https://competition.delphi.fyi/markets.json",
    feedbackUrl: env.DELPHI_FEEDBACK_URL || "https://feedback.delphi.fyi/v1/feedback",
    firecrawlUrl: env.FIRECRAWL_BASE_URL || "https://api.firecrawl.dev/v1",
  };
}

const env: Record<string, string | undefined> = {};

const passthrough = new Set([
  "DELPHI_API_ACCESS_KEY",
  "FIRECRAWL_API_KEY",
  "LIVE_SUBMIT",
  "X_AGENT_ID",
  "X_AGENT_HARNESS",
  "X_AGENT_MODEL",
  "DELPHI_BASE_URL",
  "DELPHI_MARKETS_URL",
  "DELPHI_FEEDBACK_URL",
  "FIRECRAWL_BASE_URL",
]);

for (const [k, v] of Object.entries(process.env)) {
  if (passthrough.has(k) && typeof v === "string") env[k] = v;
}

/** Never print values of credential env vars; key names only. */
export const config = {
  get DELPHI_API_ACCESS_KEY() {
    return env.DELPHI_API_ACCESS_KEY;
  },
  get FIRECRAWL_API_KEY() {
    return env.FIRECRAWL_API_KEY;
  },
  get LIVE_SUBMIT() {
    return env.LIVE_SUBMIT;
  },
  get X_AGENT_ID() {
    return env.X_AGENT_ID;
  },
  get X_AGENT_HARNESS() {
    return env.X_AGENT_HARNESS;
  },
  get X_AGENT_MODEL() {
    return env.X_AGENT_MODEL;
  },
  get DELPHI_BASE_URL() {
    return env.DELPHI_BASE_URL;
  },
  get DELPHI_MARKETS_URL() {
    return env.DELPHI_MARKETS_URL;
  },
  get DELPHI_FEEDBACK_URL() {
    return env.DELPHI_FEEDBACK_URL;
  },
  get FIRECRAWL_BASE_URL() {
    return env.FIRECRAWL_BASE_URL;
  },
};

import type { AgentConfig } from "./config.js";
import type { CompetitionMarket, DelphiApi, EntryState, EvidenceLimits, EvidenceTerms, SubmissionRecord } from "./types.js";
import { loadFixtureMarkets, mockEntryState, mockLimits, mockSubmissions, mockTerms } from "./fixtures.js";

/** Mock client: all external calls stubbed, deterministic, offline. */
export function mockDelphiApi(): DelphiApi {
  return {
    mode: "mock",
    getLimits: async () => mockLimits(),
    getTerms: async () => mockTerms(),
    getEntryState: async (address: string) => mockEntryState(address),
    listSubmissions: async (q: { market?: string }) => mockSubmissions(q.market),
    listCompetitionMarkets: async () => loadFixtureMarkets(),
  };
}

/** Live client built on the official SDK EvidenceClient. Read-only routes only;
 *  submit lives in submitter.ts behind the liveSubmit guard. */
export function liveDelphiApi(cfg: AgentConfig): DelphiApi {
  if (!cfg.delphiApiKey) throw new Error("live mode needs DELPHI_API_ACCESS_KEY");
  // Lazy import keeps mock runs fully independent of SDK network wiring.
  const sdk: typeof import("@gensyn-ai/gensyn-delphi-sdk") = awaitImportSdk();
  const client = new sdk.EvidenceClient({
    baseUrl: cfg.baseUrl,
    apiKey: cfg.delphiApiKey,
    agentId: cfg.agentId,
    agentHarness: cfg.agentHarness,
    agentModel: cfg.agentModel,
  });
  const entryStateCache = new Map<string, EntryState>();
  return {
    mode: "live",
    getLimits: async () => (await client.getLimits()).data,
    getTerms: async () => (await client.getTerms()).data,
    getEntryState: async (address: string) => {
      if (entryStateCache.has(address)) return entryStateCache.get(address)!;
      const { data } = await client.getEntryState(address);
      entryStateCache.set(address, data as EntryState);
      return data as EntryState;
    },
    listSubmissions: async (q: { market?: string }) => {
      const out: SubmissionRecord[] = [];
      let cursor: string | undefined = undefined;
      for (let i = 0; i < 10; i++) {
        const { data } = await client.listSubmissions({
          market: q.market,
          cursor,
          limit: 100,
        });
        out.push(...(data.items as unknown as SubmissionRecord[]));
        if (!data.nextCursor) break;
        cursor = data.nextCursor;
      }
      return out;
    },
    listCompetitionMarkets: async () => {
      const res = await fetch(cfg.marketsUrl);
      if (!res.ok) throw new Error(`markets.json fetch failed: ${res.status}`);
      return (await res.json()) as CompetitionMarket[];
    },
  };
}

let sdkPromise: Promise<typeof import("@gensyn-ai/gensyn-delphi-sdk")> | null = null;
function awaitImportSdk(): typeof import("@gensyn-ai/gensyn-delphi-sdk") {
  // Synchronous by design: callers of liveDelphiApi must await makeLive instead.
  throw new Error(
    "live mode is async-initialized; call createDelphiApi() instead of liveDelphiApi()",
  );
}

export async function createDelphiApi(cfg: AgentConfig): Promise<DelphiApi> {
  if (cfg.mode === "mock") return mockDelphiApi();
  const sdk = await import("@gensyn-ai/gensyn-delphi-sdk");
  const client = new sdk.EvidenceClient({
    baseUrl: cfg.baseUrl,
    apiKey: cfg.delphiApiKey!,
    agentId: cfg.agentId,
    agentHarness: cfg.agentHarness,
    agentModel: cfg.agentModel,
  });
  const entryStateCache = new Map<string, EntryState>();
  return {
    mode: "live",
    getLimits: async () => (await client.getLimits()).data,
    getTerms: async () => (await client.getTerms()).data,
    getEntryState: async (address: string) => {
      if (entryStateCache.has(address)) return entryStateCache.get(address)!;
      const { data } = await client.getEntryState(address);
      const state = data as unknown as EntryState;
      entryStateCache.set(address, state);
      return state;
    },
    listSubmissions: async (q: { market?: string }) => {
      const out: SubmissionRecord[] = [];
      let cursor: string | undefined;
      for (let i = 0; i < 10; i++) {
        const { data } = await client.listSubmissions({ market: q.market, cursor, limit: 100 });
        out.push(...(data.items as unknown as SubmissionRecord[]));
        if (!data.nextCursor ?? null) break;
        cursor = data.nextCursor ?? undefined;
      }
      return out;
    },
    listCompetitionMarkets: async () => {
      const res = await fetch(cfg.marketsUrl);
      if (!res.ok) throw new Error(`markets.json fetch failed: ${res.status}`);
      return (await res.json()) as CompetitionMarket[];
    },
  };
}

